/**
 * canonical-contract-font.ts
 *
 * Fonte canônica determinística para o sistema de contratos GOAT Bar.
 * Binários WOFF2 embutidos em Base64 garantem que o Preview (browser do operador)
 * e o PDF oficial (Chromium em Linux via Cloudflare Browser Run) renderizem
 * exatamente os mesmos glifos, larguras, alturas de linha e métricas tipográficas.
 *
 * Zero dependência de internet ou CDN em tempo de execução.
 */

export const CANONICAL_FONT_FAMILY = "GoatBarContractFont";

export const CANONICAL_FONT_REGULAR_BASE64 = "";
export const CANONICAL_FONT_BOLD_BASE64 = "";

export const CANONICAL_FONT_FACE_CSS = `
@font-face {
  font-family: "${CANONICAL_FONT_FAMILY}";
  font-style: normal;
  font-weight: 400;
  font-display: block;
  src: url(data:font/woff2;base64,${CANONICAL_FONT_REGULAR_BASE64}) format("woff2");
}

@font-face {
  font-family: "${CANONICAL_FONT_FAMILY}";
  font-style: normal;
  font-weight: 700;
  font-display: block;
  src: url(data:font/woff2;base64,${CANONICAL_FONT_BOLD_BASE64}) format("woff2");
}
`;
